//! Config for CLI

use anyhow::Context;
use std::{fs::read_to_string, io::Error as IoError, path::PathBuf};
use thiserror::Error;

use serde::{Deserialize, Serialize};

/// Environment configuration for CLI commands that use the database.
pub struct DataConfig {
    /// PostgreSQL connection string.
    pub connection_string: String,
}

impl DataConfig {
    /// Reads the database connection string from the environment.
    ///
    /// # Errors
    /// Returns an error if `DATABASE_URL` is missing or contains non-Unicode data.
    pub fn from_env() -> anyhow::Result<Self> {
        Ok(Self {
            connection_string: std::env::var("DATABASE_URL").context("DATABASE_URL must be set")?,
        })
    }
}

/// Configuration for capturing declarations for the stored member cohort.
#[derive(Serialize, Deserialize)]
pub struct DeclarationFetcherConfig {
    /// Root directory for ingestion datasets.
    pub data_dir: PathBuf,
    /// Nonzero API page size; validated when constructing the HTTP adapter.
    pub batch_size: u8,
}

impl TryFrom<&PathBuf> for DeclarationFetcherConfig {
    type Error = CliConfigError;

    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        Ok(rust_yaml::from_str(&raw)?)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct FetcherConfig {
    /// Size of API batches
    pub batch_size: u8,
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for FetcherConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct LoaderConfig {
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for LoaderConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Error, Debug)]
/// Collection of errors when parsing configuration
pub enum CliConfigError {
    #[error("yaml malformatted")]
    /// Yaml cannot be parsed
    FormattingError(#[from] rust_yaml::Error),
    #[error("unable to read config")]
    /// Config path invalid
    FileNotFound(#[from] IoError),
}

/// Runtime configuration for offline statistical declaration resolution.
#[derive(Deserialize)]
pub struct DeclarationResolverConfig {
    /// Root directory containing the existing ingestion run.
    pub data_dir: PathBuf,
    /// Maximum profile candidates and expanded observation pairs.
    #[serde(default = "default_candidate_budget")]
    pub candidate_budget: usize,
}
const fn default_candidate_budget() -> usize {
    1_000_000
}
impl TryFrom<&PathBuf> for DeclarationResolverConfig {
    type Error = anyhow::Error;
    fn try_from(path: &PathBuf) -> Result<Self, Self::Error> {
        let config: Self = rust_yaml::from_str(&read_to_string(path)?)?;
        anyhow::ensure!(
            config.candidate_budget > 0,
            "candidate_budget must be positive"
        );
        Ok(config)
    }
}
use std::future::Future;

use schemars::{JsonSchema, Schema, generate::SchemaSettings};
use serde::Serialize;
use strum::IntoEnumIterator;

use super::{CliSuccess, response::ErrorResponse};
use crate::domain::models::entity_ingestion::DeclarationIngestionStage;

fn schema<T: JsonSchema>() -> Schema {
    SchemaSettings::draft2020_12()
        .for_serialize()
        .into_generator()
        .into_root_schema_for::<T>()
}

trait ResponseSchema {
    fn schema() -> Schema;
}

impl<T: Serialize + JsonSchema, E> ResponseSchema for Result<CliSuccess<T>, E> {
    fn schema() -> Schema {
        schema::<T>()
    }
}

pub(super) trait HandlerSchema<Args> {
    fn response_schema(self) -> Schema;
}

macro_rules! handler_schema {
    ($($arg:ident),*) => {
        impl<F, Fut, $($arg,)*> HandlerSchema<($($arg,)*)> for F
        where
            F: FnOnce($($arg),*) -> Fut,
            Fut: Future,
            Fut::Output: ResponseSchema,
        {
            fn response_schema(self) -> Schema {
                <Fut::Output as ResponseSchema>::schema()
            }
        }
    };
}

handler_schema!();
handler_schema!(A);
handler_schema!(A, B);
handler_schema!(A, B, C);

fn section(label: &str, schema: &Schema) -> String {
    format!(
        "{label}\n{}\n",
        serde_json::to_string_pretty(schema).expect("JSON schema serializes")
    )
}

fn failure() -> String {
    format!(
        "Success: one JSON document on stdout, exit 0.\nCommand failure: one JSON document on stderr, exit 1.\nClap argument errors and help use Clap's text output.\nSchemas use JSON Schema draft 2020-12.\n\n{}",
        section("Failure JSON schema:", &schema::<ErrorResponse>())
    )
}

pub(super) fn single<Args>(handler: impl HandlerSchema<Args>) -> String {
    format!(
        "{}\n{}",
        section("Success JSON schema:", &handler.response_schema()),
        failure()
    )
}

pub(super) fn declarations() -> String {
    let mut help = String::new();
    for stage in DeclarationIngestionStage::iter() {
        let mut schema = match stage {
            DeclarationIngestionStage::Fetch => super::fetch_declarations.response_schema(),
            DeclarationIngestionStage::Clean => super::clean_declarations.response_schema(),
            DeclarationIngestionStage::Resolve => super::resolve_declarations.response_schema(),
            DeclarationIngestionStage::Load => super::load_declarations.response_schema(),
        };
        if stage == DeclarationIngestionStage::Fetch {
            schema
                .as_object_mut()
                .expect("response schema is an object")["properties"]["stage"]["const"] =
                serde_json::to_value(&stage).expect("stage serializes");
        }
        let label = serde_json::to_value(&stage).expect("stage serializes");
        help.push_str(&section(
            &format!(
                "Success JSON schema ({}):",
                label.as_str().expect("stage is a string")
            ),
            &schema,
        ));
        help.push('\n');
    }
    help.push_str(&failure());
    help
}
//! CLI inbound port

use schemars::JsonSchema;
use std::{path::PathBuf, str::FromStr};

use clap::{Parser, Subcommand};
use serde::Serialize;

use crate::{
    domain::{
        models::declaration_loading::DeclarationLoadOutcome,
        models::entity_ingestion::{
            DeclarationIngestionStage, EntityIngestionRequest, IngestionKey, MemberIngestionStage,
        },
        services::declaration_cleaning::DeclarationCleanerService,
        services::declaration_fetch::DeclarationFetcherService,
        services::declaration_loading::DeclarationLoaderService,
        services::declaration_resolution::DeclarationResolverService,
        services::entity_ingestion::{
            EntityFetcherService, EntityIngesterService, FetcherService, IngesterService,
        },
    },
    inbound::cli::config::{
        DataConfig, DeclarationFetcherConfig, DeclarationResolverConfig, FetcherConfig,
        LoaderConfig,
    },
    outbound::{ExposedDataPipeline, ExposedDatabase, ParliamentApiClient, WeldrsFunderScorer},
};

pub mod config;
mod migrate;
pub mod response;
mod response_help;

pub use migrate::{MigrateArgs, run_migrate};
pub use response::{CliSuccess, IntoResponse, Response};

/// CLI entrypoint for the `exposed` project
#[derive(Parser)]
pub struct ExposedCli {
    /// Commands for CLI
    #[command(subcommand)]
    pub command: Commands,
}

/// Run a server, prepare application data, or apply database migrations
#[derive(Subcommand)]
pub enum Commands {
    /// Start an instance of the `exposed` server
    Server,
    /// Options to run the `exposed` data pipeline
    Data(DataArgs),
    /// Apply database migrations explicitly.
    Migrate(MigrateArgs),
}

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    /// Show the latest ingestion key and directory path.
    #[command(after_long_help = response_help::single(latest))]
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
    },
    /// Copy the latest raw capture into a new ingestion run.
    #[command(after_long_help = response_help::single(copy_latest_raw))]
    CopyLatestRaw {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Destination ingestion key. Defaults to a fresh UUID-v7.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    /// Declarations data retrieval commands.
    ///
    /// Declaration ingestion has four stages that must be run in the following order:
    ///   1. fetch
    ///   2. clean
    ///   3. resolve
    ///   4. load
    #[command(
        verbatim_doc_comment,
        after_long_help = response_help::declarations()
    )]
    Declarations {
        /// Stage to run: fetch, clean, resolve, or load.
        #[arg(value_parser = ["fetch", "clean", "resolve", "load"])]
        stage: String,
        /// YAML configuration containing the declaration `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Ingestion run to clean, resolve, or load.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    /// Members data retrieval commands
    ///
    /// Member has two stages that must be run in the following order:
    ///   1. fetch
    ///   2. load
    #[command(
        verbatim_doc_comment,
        after_long_help = response_help::single(members)
    )]
    Members {
        /// Stage to run: fetch or load.
        #[arg(value_parser = ["fetch", "load"])]
        stage: String,
        #[arg(long)]
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// Command failures remain in the response until [`Response::write_to`] is called.
///
/// Failures include:
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> Response {
    match args.command {
        DataCommands::Latest { config } => latest(config).await.into_response(),
        DataCommands::CopyLatestRaw {
            config,
            ingestion_key,
        } => copy_latest_raw(config, ingestion_key).await.into_response(),
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => declarations(stage, config, ingestion_key).await,
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => members(stage, config, ingestion_key).await.into_response(),
    }
}

#[derive(Serialize, JsonSchema)]
struct IngestionResponse<T> {
    /// Ingestion result, or null when the store has no source runs.
    ingestion: Option<T>,
}

#[derive(Serialize, JsonSchema)]
struct IngestionLocation {
