#[test]
fn long_help_documents_yaml_without_reading_configuration() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    for (command, expected, database_count) in [
        ("latest", vec!["data_dir (required)"], 0),
        ("copy-latest-raw", vec!["data_dir (required)"], 0),
        (
            "declarations",
            vec![
                "fetch:",
                "clean:",
                "resolve:",
                "load:",
                "batch_size (required): API page size, from 1 to 255.",
                "candidate_budget (optional, default 1000000)",
                "Must be positive.",
            ],
            2,
        ),
        (
            "members",
            vec!["fetch:", "load:", "batch_size (required)"],
            1,
        ),
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path())
            .env_remove("DATABASE_URL")
            .args(["data", command, "--config", "missing.yaml", "--help"])
            .output()?;
        assert!(output.status.success(), "{command}");
        assert!(output.stderr.is_empty(), "{command}");
        let help = String::from_utf8(output.stdout)?;
        // Clap wraps prose to the terminal width.
        let help = help.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(help.contains("Path to a YAML configuration file."), "{help}");
        assert!(
            help.contains("Relative data_dir paths resolve against the current working directory."),
            "{help}"
        );
        for text in expected {
            assert!(help.contains(text), "missing {text:?} in {help}");
        }
        assert_eq!(help.matches("DATABASE_URL").count(), database_count, "{help}");
        if command == "declarations" {
            assert!(help.contains("fetch: batch_size"), "{help}");
            assert!(help.contains("clean: data_dir"), "{help}");
            assert!(help.contains("load: data_dir"), "{help}");
        }
        if command == "members" {
            let (fetch, load) = help.split_once("load:").expect("load section exists");
            assert!(!fetch.contains("DATABASE_URL"), "{help}");
            assert!(load.contains("DATABASE_URL"), "{help}");
        }
        let short = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(temporary.path())
            .env_remove("DATABASE_URL")
            .args(["data", command, "-h"])
            .output()?;
        assert!(short.status.success());
        assert!(!String::from_utf8(short.stdout)?.contains("candidate_budget"));
    }
    assert_eq!(std::fs::read_dir(temporary.path())?.count(), 0);
    Ok(())
}

#[test]
fn documented_resolver_default_matches_yaml_parser() -> anyhow::Result<()> {
    use exposed::inbound::cli::config::DeclarationResolverConfig;

    let temporary = TempDir::new()?;
    let path = temporary.path().join("config.yaml");
    std::fs::write(&path, "data_dir: datasets\n")?;
    let config = DeclarationResolverConfig::try_from(&path)?;
    assert_eq!(config.candidate_budget, 1_000_000);
    assert_eq!(config.data_dir, std::path::PathBuf::from("datasets"));
    std::fs::write(&path, "candidate_budget: 1\n")?;
    assert!(DeclarationResolverConfig::try_from(&path).is_err());
    std::fs::write(&path, "data_dir: datasets\ncandidate_budget: 0\n")?;
    assert!(DeclarationResolverConfig::try_from(&path).is_err());
    Ok(())
}
